SELECT SCHEDULER_ID, SCHEDULER_NAME, SCHEDULER_DESCRIPTION, CRON_EXPRESSION, JOB_CLASS_NAME, IS_ENABLED, TO_CHAR(REG_DT, 'YYYY-MM-DD HH24:MI:SS') AS REG_DT, REG_USER_ID, TO_CHAR(UPD_DT, 'YYYY-MM-DD HH24:MI:SS') AS UPD_DT, UPD_USER_ID FROM SCHEDULER_CONFIG WHERE 1=1
AND (SCHEDULER_NAME LIKE '%' || #{searchWrd} || '%' OR SCHEDULER_DESCRIPTION LIKE '%' || #{searchWrd} || '%')
AND IS_ENABLED = #{isEnabled}
ORDER BY SCHEDULER_ID DESC
LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

SELECT COUNT(*) FROM SCHEDULER_CONFIG WHERE 1=1
AND (SCHEDULER_NAME LIKE '%' || #{searchWrd} || '%' OR SCHEDULER_DESCRIPTION LIKE '%' || #{searchWrd} || '%')
AND IS_ENABLED = #{isEnabled}
